;------------------------------------------------------------------------------
; 7FC9H - Select the character matrix
; C: back to the normal 26-column character set; NC: 16-dot (kanji) matrix, 19
; columns, if the display driver supports it (DBLMATR).  Resets MODE 1.
;------------------------------------------------------------------------------
SETMATRIX:
	ld hl,DSPMODE                   ; 7FC9  2142fe
	jr nc,SETKANJI                  ; 7FCC  3021
	call SETANK                     ; 7FCE  cd0901
	res 2,(hl)                      ; 7FD1  cb96
	xor a                           ; 7FD3  af
	ld (0FD00H),a                   ; 7FD4  3200fd
	ld a,(STAT2)                    ; 7FD7  3ac6f3
	and 0F7H                        ; 7FDA  e6f7
	call SYMWRITE2                  ; 7FDC  cdff74
	ld a,1AH                        ; 7FDF  3e1a
SETWIDTH:
	ld (LWIDTHW),a                  ; 7FE1  3218fe
	ld hl,BMODE                     ; 7FE4  21bcf1
	res 6,(hl)                      ; 7FE7  cbb6
	xor a                           ; 7FE9  af
	call CGMODE                     ; 7FEA  cd3301
	and a                           ; 7FED  a7
	ret                             ; 7FEE  c9
SETKANJI:
	ld a,(BMODE)                    ; 7FEF  3abcf1
	rla                             ; 7FF2  17
	ret c                           ; 7FF3  d8
